//! Macros that turn the tables generated by `build.rs` into enums. The
//! generated file only lists data; all behaviour lives here so it is reviewed,
//! formatted and linted like the rest of the crate.

/// `Display`, `AsRef<str>`, `TryFrom<&str>` and (with the `serde` feature)
/// string (de)serialization for a type with `as_str()` and `FromStr`.
macro_rules! impl_str_traits {
    ($name:ident) => {
        impl ::core::fmt::Display for $name {
            fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
                f.write_str(self.as_str())
            }
        }

        impl AsRef<str> for $name {
            fn as_ref(&self) -> &str {
                self.as_str()
            }
        }

        impl TryFrom<&str> for $name {
            type Error = crate::ParseError;

            fn try_from(value: &str) -> Result<Self, Self::Error> {
                value.parse()
            }
        }

        #[cfg(feature = "serde")]
        impl ::serde::Serialize for $name {
            fn serialize<S: ::serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
                serializer.serialize_str(self.as_str())
            }
        }

        #[cfg(feature = "serde")]
        impl<'de> ::serde::Deserialize<'de> for $name {
            fn deserialize<D: ::serde::Deserializer<'de>>(
                deserializer: D,
            ) -> Result<Self, D::Error> {
                let value = <String as ::serde::Deserialize>::deserialize(deserializer)?;

                value.parse().map_err(::serde::de::Error::custom)
            }
        }
    };
}

/// Defines [`Chain`](crate::Chain) and [`SUPPORTED_CHAIN_IDS`](crate::SUPPORTED_CHAIN_IDS).
macro_rules! define_chains {
    ($(
        $(#[$attr:meta])*
        $variant:ident {
            name: $name:literal,
            id: $id:literal,
            evm: $evm:literal,
            testnet: $testnet:literal,
            logo: $logo:expr $(,)?
        }
    ),* $(,)?) => {
        /// A chain supported by the token list (the `SupportedChain` keys of `data.json`).
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        #[non_exhaustive]
        pub enum Chain {
            $($(#[$attr])* $variant,)*
        }

        /// Chain ID of every [`Chain`], in [`Chain::ALL`] order.
        pub const SUPPORTED_CHAIN_IDS: &[u64] = &[$($id,)*];

        impl Chain {
            /// Every supported chain, in `supported-chains.json` order.
            pub const ALL: &'static [Chain] = &[$(Chain::$variant,)*];

            /// The chain's key in `data.json` (e.g. `"bob"`, `"op-mainnet"`).
            pub const fn as_str(self) -> &'static str {
                match self {
                    $(Chain::$variant => $name,)*
                }
            }

            /// Numeric chain ID, as used for `chainId` in the generated token lists.
            ///
            /// Non-EVM chains use the IDs from `supported-chains.json` (e.g.
            /// [`SOLANA_CHAIN_ID`](crate::SOLANA_CHAIN_ID)).
            pub const fn id(self) -> u64 {
                match self {
                    $(Chain::$variant => $id,)*
                }
            }

            /// Looks a chain up by its numeric chain ID.
            pub const fn from_id(id: u64) -> Option<Chain> {
                match id {
                    $($id => Some(Chain::$variant),)*
                    _ => None,
                }
            }

            /// Whether the chain uses EVM addresses. `false` for Solana, the
            /// Bitcoin networks and Tron (TVM, base58 addresses).
            pub const fn is_evm(self) -> bool {
                match self {
                    $(Chain::$variant => $evm,)*
                }
            }

            /// Whether the chain is a test network.
            pub const fn is_testnet(self) -> bool {
                match self {
                    $(Chain::$variant => $testnet,)*
                }
            }

            /// Logo file name in `data/chains/`, from `data/chains/chains.json`.
            pub(crate) const fn logo_file(self) -> Option<&'static str> {
                match self {
                    $(Chain::$variant => $logo,)*
                }
            }
        }

        impl ::core::str::FromStr for Chain {
            type Err = crate::ParseError;

            fn from_str(value: &str) -> Result<Self, Self::Err> {
                match value {
                    $($name => Ok(Chain::$variant),)*
                    _ => Err(crate::ParseError::new("chain", value)),
                }
            }
        }

        impl_str_traits!(Chain);
    };
}

/// Defines [`TokenId`](crate::TokenId).
macro_rules! define_token_ids {
    ($(
        $(#[$attr:meta])*
        $variant:ident => $id:literal
    ),* $(,)?) => {
        /// Identifier of a token: the name of its `data/tokens/<ID>/` directory.
        ///
        /// Variants keep the directory casing; characters that are not valid
        /// in Rust identifiers are spelled out (`BTC.b` → `BTC_b`,
        /// `BTC+` → `BTC_PLUS`). Use [`TokenId::as_str`] for the original ID.
        #[allow(non_camel_case_types, clippy::upper_case_acronyms)]
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        #[non_exhaustive]
        pub enum TokenId {
            $($(#[$attr])* $variant,)*
        }

        impl TokenId {
            /// Every token ID, sorted case-insensitively.
            pub const ALL: &'static [TokenId] = &[$(TokenId::$variant,)*];

            /// The token ID string, e.g. `"BTC.b"`.
            pub const fn as_str(self) -> &'static str {
                match self {
                    $(TokenId::$variant => $id,)*
                }
            }
        }

        impl ::core::str::FromStr for TokenId {
            type Err = crate::ParseError;

            fn from_str(value: &str) -> Result<Self, Self::Err> {
                match value {
                    $($id => Ok(TokenId::$variant),)*
                    _ => Err(crate::ParseError::new("token id", value)),
                }
            }
        }

        impl_str_traits!(TokenId);
    };
}

/// Defines a subset of [`TokenId`](crate::TokenId) (e.g. `NativeTokenId`),
/// convertible to `TokenId` with `From` and back with `TryFrom`.
macro_rules! define_token_id_subset {
    (
        $(#[$meta:meta])*
        $name:ident {
            $(
                $(#[$attr:meta])*
                $variant:ident
            ),* $(,)?
        }
    ) => {
        $(#[$meta])*
        #[allow(non_camel_case_types, clippy::upper_case_acronyms)]
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        #[non_exhaustive]
        pub enum $name {
            $($(#[$attr])* $variant,)*
        }

        impl $name {
            /// Every token ID in this set, in [`TokenId::ALL`](crate::TokenId::ALL) order.
            pub const ALL: &'static [$name] = &[$($name::$variant,)*];

            /// The corresponding [`TokenId`](crate::TokenId).
            pub const fn token_id(self) -> crate::TokenId {
                match self {
                    $($name::$variant => crate::TokenId::$variant,)*
                }
            }

            /// The token ID string, e.g. `"BTC"`.
            pub const fn as_str(self) -> &'static str {
                self.token_id().as_str()
            }
        }

        impl From<$name> for crate::TokenId {
            fn from(id: $name) -> Self {
                id.token_id()
            }
        }

        impl TryFrom<crate::TokenId> for $name {
            type Error = crate::TryFromTokenIdError;

            fn try_from(id: crate::TokenId) -> Result<Self, Self::Error> {
                match id {
                    $(crate::TokenId::$variant => Ok($name::$variant),)*
                    _ => Err(crate::TryFromTokenIdError::new(stringify!($name), id)),
                }
            }
        }

        impl ::core::str::FromStr for $name {
            type Err = crate::ParseError;

            fn from_str(value: &str) -> Result<Self, Self::Err> {
                value
                    .parse::<crate::TokenId>()
                    .ok()
                    .and_then(|id| $name::try_from(id).ok())
                    .ok_or_else(|| crate::ParseError::new(stringify!($name), value))
            }
        }

        impl_str_traits!($name);
    };
}
